1	#!/usr/bin/env node
2	/**
3	 * Entire Trail — Claude Code statusline helper
4	 *
5	 * Shows a clickable "Trail #N <status>" link in the Claude Code statusline when
6	 * the current git branch has an Entire trail connected to it, mirroring the
7	 * footer link from the Pi trails extension.
8	 *
9	 * Design notes:
10	 *  - Statuslines are polled very frequently, so this script must be fast and
11	 *    must never block on git/network. It serves a cached result immediately and
12	 *    spawns a *detached* background refresh (throttled) that talks to the
13	 *    `entire` CLI and rewrites the cache for the next poll.
14	 *  - Auth is delegated entirely to the `entire` CLI (`entire trail list --json`)
15	 *    so we honour the user's current context + keychain instead of
16	 *    reimplementing token storage (which has drifted across CLI versions). When
17	 *    the CLI reports it is not logged in, we surface a "run `entire login`" hint.
18	 *
19	 * Claude Code invokes this with session JSON on stdin; we only need `cwd`.
20	 * Invoked with `--refresh <cwd> <cacheFile>` it performs the slow lookup and
21	 * writes the cache, printing nothing.
22	 */
23	
24	import { execFileSync, spawn } from "node:child_process";
25	import { mkdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
26	import { homedir } from "node:os";
27	import { join } from "node:path";
28	import { createHash } from "node:crypto";
29	
30	// Serve cache without triggering a refresh if it is younger than this.
31	const FRESH_MS = 60_000;
32	// Don't spawn another background refresh if one started this recently.
33	const REFRESH_LOCK_MS = 10_000;
34	// Hard cap on how long the background CLI lookup may take.
35	const REFRESH_TIMEOUT_MS = 15_000;
36	
37	const CACHE_DIR = join(
38		process.env.XDG_CACHE_HOME || join(homedir(), ".cache"),
39		"entire-trail-statusline",
40	);
41	
42	const RESET = "\x1b[0m";
43	const CYAN = "\x1b[36m";
44	const DIM = "\x1b[2m";
45	
46	function color(code, text) {
47		return `${code}${text}${RESET}`;
48	}
49	
50	// OSC-8 terminal hyperlink — same scheme the Pi extension uses for its footer.
51	function hyperlink(url, label) {
52		return `\x1b]8;;${url}\x07${label}\x1b]8;;\x07`;
53	}
54	
55	function git(cwd, args) {
56		try {
57			return (
58				execFileSync("git", args, {
59					cwd,
60					encoding: "utf8",
61					timeout: 2000,
62					stdio: ["ignore", "pipe", "ignore"],
63				}).trim() || null
64			);
65		} catch {
66			return null;
67		}
68	}
69	
70	function getBranch(cwd) {
71		return git(cwd, ["branch", "--show-current"]);
72	}
73	
74	function getRemote(cwd) {
75		const remote = git(cwd, ["remote", "get-url", "origin"]);
76		if (!remote) return null;
77	
78		const entireMatch = remote.match(/^entire:\/\/[^/]+\/gh\/([^/]+)\/([^/?#]+?)(?:\.git)?(?:[?#].*)?$/);
79		if (entireMatch) return { org: decodeURIComponent(entireMatch[1]), repo: decodeURIComponent(entireMatch[2]) };
80	
81		const githubMatch = remote.match(/github\.com[/:]([^/]+)\/(.+?)(?:\.git)?$/);
82		return githubMatch ? { org: githubMatch[1], repo: githubMatch[2] } : null;
83	}
84	
85	function cacheKey(remote, branch) {
86		return createHash("sha1").update(`${remote.org}/${remote.repo}|${branch}`).digest("hex").slice(0, 16);
87	}
88	
89	function readCache(file) {
90		try {
91			const parsed = JSON.parse(readFileSync(file, "utf8"));
92			if (parsed && typeof parsed.ts === "number" && parsed.result) return parsed;
93		} catch {
94			// Missing or corrupt cache — treat as absent.
95		}
96		return null;
97	}
98	
99	function writeCache(file, payload) {
100		try {
101			mkdirSync(CACHE_DIR, { recursive: true });
102			writeFileSync(file, JSON.stringify(payload));
103		} catch {
104			// A failed cache write just means we re-resolve next time.
105		}
106	}
107	
108	function maybeSpawnRefresh(cwd, cacheFile) {
109		const lock = `${cacheFile}.lock`;
110		try {
111			if (Date.now() - statSync(lock).mtimeMs < REFRESH_LOCK_MS) return; // refresh already in flight
112		} catch {
113			// No lock yet.
114		}
115		try {
116			mkdirSync(CACHE_DIR, { recursive: true });
117			writeFileSync(lock, String(Date.now()));
118		} catch {
119			// If we can't take the lock, still attempt the refresh.
120		}
121		const child = spawn(process.execPath, [process.argv[1], "--refresh", cwd, cacheFile], {
122			detached: true,
123			stdio: "ignore",
124		});
125		child.unref();
126	}
127	
128	// Build a web URL for the trail. Prefer whatever the CLI hands us; otherwise
129	// fall back to the canonical entire.io trail path used by the Pi extension.
130	function trailURL(trail, remote, branch) {
131		const fromApi = trail.url || trail.html_url || trail.web_url;
132		if (typeof fromApi === "string" && fromApi.startsWith("http")) return fromApi;
133		if (!remote || !trail.number) return undefined;
134		const slug = String(trail.title || branch || "")
135			.toLowerCase()
136			.replace(/[^a-z0-9]+/g, "-")
137			.replace(/^-+|-+$/g, "")
138			.slice(0, 60);
139		return `https://entire.io/gh/${remote.org}/${remote.repo}/trails/${trail.number}${slug ? `/${slug}` : ""}`;
140	}
141	
142	// The CLI's JSON shape is defensive-mapped: field names have varied across
143	// versions, so accept the common aliases.
144	function normalizeTrail(raw) {
145		if (!raw || typeof raw !== "object") return null;
146		const number = raw.number ?? raw.trail_number ?? raw.id;
147		const branch = raw.branch ?? raw.branch_name ?? raw.head_branch ?? raw.head;
148		if (number == null || !branch) return null;
149		return {
150			number,
151			branch: String(branch),
152			title: raw.title ?? raw.name ?? null,
153			status: raw.status ?? raw.state ?? null,
154			url: raw.url ?? raw.html_url ?? raw.web_url ?? null,
155		};
156	}
157	
158	function parseTrails(stdout) {
159		let json;
160		try {
161			json = JSON.parse(stdout);
162		} catch {
163			return [];
164		}
165		const list = Array.isArray(json) ? json : Array.isArray(json?.trails) ? json.trails : [];
166		return list.map(normalizeTrail).filter(Boolean);
167	}
168	
169	function render(result) {
170		if (!result) return "";
171		if (result.status === "found") {
172			const label = `Trail #${result.number}${result.trailStatus ? ` ${result.trailStatus}` : ""}`;
173			return color(CYAN, result.url ? hyperlink(result.url, label) : label);
174		}
175		if (result.status === "auth") return color(DIM, "Trail: run `entire login`");
176		if (result.status === "error" && result.message) return color(DIM, `Trail: ${result.message}`);
177		// "no-trail" and anything else render as empty (segment-only mode).
178		return "";
179	}
180	
181	// --- background refresh mode ---------------------------------------------
182	
183	function runRefresh(cwd, cacheFile) {
184		let result;
185		try {
186			const stdout = execFileSync(
187				"entire",
188				["trail", "list", "--json", "--status", "any", "-n", "100"],
189				{ cwd, encoding: "utf8", timeout: REFRESH_TIMEOUT_MS, stdio: ["ignore", "pipe", "pipe"] },
190			);
191			const branch = getBranch(cwd);
192			const remote = getRemote(cwd);
193			const trail = parseTrails(stdout).find((t) => t.branch === branch);
194			result = trail
195				? {
196						status: "found",
197						number: trail.number,
198						trailStatus: trail.status,
199						url: trailURL(trail, remote, branch),
200					}
201				: { status: "no-trail" };
202		} catch (err) {
203			const stderr = (err?.stderr?.toString?.() || "").trim();
204			const msg = (stderr || err?.message || "").toLowerCase();
205			if (/not logged in|authentication required|unauthorized|run 'entire login'|please log in/.test(msg)) {
206				result = { status: "auth" };
207			} else if (/repository not found|not found|404|not enabled|no trail/.test(msg)) {
208				// Repo isn't tracked by Entire (or has no trails) — render nothing.
209				result = { status: "no-trail" };
210			} else {
211				// Keep it short; the statusline only has room for a hint.
212				result = { status: "error", message: (stderr || "lookup failed").split("\n")[0].slice(0, 60) };
213			}
214		}
215		writeCache(cacheFile, { ts: Date.now(), result });
216	}
217	
218	// --- statusline (fast) mode ----------------------------------------------
219	
220	function readStdinCwd() {
221		try {
222			const raw = readFileSync(0, "utf8");
223			const input = raw ? JSON.parse(raw) : {};
224			return input?.workspace?.current_dir || input?.cwd || process.cwd();
225		} catch {
226			return process.cwd();
227		}
228	}
229	
230	function runStatusline() {
231		const cwd = readStdinCwd();
232		const branch = getBranch(cwd);
233		const remote = getRemote(cwd);
234		// Not a git repo, detached HEAD, or no resolvable remote → nothing to show.
235		if (!branch || !remote) return;
236	
237		const cacheFile = join(CACHE_DIR, `${cacheKey(remote, branch)}.json`);
238		const cached = readCache(cacheFile);
239		const age = cached ? Date.now() - cached.ts : Infinity;
240	
241		if (age > FRESH_MS) maybeSpawnRefresh(cwd, cacheFile);
242		if (cached) {
243			const out = render(cached.result);
244			if (out) process.stdout.write(out);
245		}
246		// No cache yet → print nothing; the trail appears once the refresh lands.
247	}
248	
249	// --- entry ----------------------------------------------------------------
250	
251	if (process.argv[2] === "--refresh") {
252		runRefresh(process.argv[3] || process.cwd(), process.argv[4]);
253	} else {
254		runStatusline();
255	}
