#!/usr/bin/env node
/**
 * Entire Trail — Claude Code statusline helper
 *
 * Shows a clickable "Trail #N <status>" link in the Claude Code statusline when
 * the current git branch has an Entire trail connected to it, mirroring the
 * footer link from the Pi trails extension.
 *
 * Design notes:
 *  - Statuslines are polled very frequently, so this script must be fast and
 *    must never block on git/network. It serves a cached result immediately and
 *    spawns a *detached* background refresh (throttled) that talks to the
 *    `entire` CLI and rewrites the cache for the next poll.
 *  - Auth is delegated entirely to the `entire` CLI (`entire trail list --json`)
 *    so we honour the user's current context + keychain instead of
 *    reimplementing token storage (which has drifted across CLI versions). When
 *    the CLI reports it is not logged in, we surface a "run `entire login`" hint.
 *
 * Claude Code invokes this with session JSON on stdin; we only need `cwd`.
 * Invoked with `--refresh <cwd> <cacheFile>` it performs the slow lookup and
 * writes the cache, printing nothing.
 */

import { execFileSync, spawn } from "node:child_process";
import { mkdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { createHash } from "node:crypto";

// Serve cache without triggering a refresh if it is younger than this.
const FRESH_MS = 60_000;
// Don't spawn another background refresh if one started this recently.
const REFRESH_LOCK_MS = 10_000;
// Hard cap on how long the background CLI lookup may take.
const REFRESH_TIMEOUT_MS = 15_000;

const CACHE_DIR = join(
	process.env.XDG_CACHE_HOME || join(homedir(), ".cache"),
	"entire-trail-statusline",
);

const RESET = "\x1b[0m";
const CYAN = "\x1b[36m";
const DIM = "\x1b[2m";

function color(code, text) {
	return `${code}${text}${RESET}`;
}

// OSC-8 terminal hyperlink — same scheme the Pi extension uses for its footer.
function hyperlink(url, label) {
	return `\x1b]8;;${url}\x07${label}\x1b]8;;\x07`;
}

function git(cwd, args) {
	try {
		return (
			execFileSync("git", args, {
				cwd,
				encoding: "utf8",
				timeout: 2000,
				stdio: ["ignore", "pipe", "ignore"],
			}).trim() || null
		);
	} catch {
		return null;
	}
}

function getBranch(cwd) {
	return git(cwd, ["branch", "--show-current"]);
}

function getRemote(cwd) {
	const remote = git(cwd, ["remote", "get-url", "origin"]);
	if (!remote) return null;

	const entireMatch = remote.match(/^entire:\/\/[^/]+\/gh\/([^/]+)\/([^/?#]+?)(?:\.git)?(?:[?#].*)?$/);
	if (entireMatch) return { org: decodeURIComponent(entireMatch[1]), repo: decodeURIComponent(entireMatch[2]) };

	const githubMatch = remote.match(/github\.com[/:]([^/]+)\/(.+?)(?:\.git)?$/);
	return githubMatch ? { org: githubMatch[1], repo: githubMatch[2] } : null;
}

function cacheKey(remote, branch) {
	return createHash("sha1").update(`${remote.org}/${remote.repo}|${branch}`).digest("hex").slice(0, 16);
}

function readCache(file) {
	try {
		const parsed = JSON.parse(readFileSync(file, "utf8"));
		if (parsed && typeof parsed.ts === "number" && parsed.result) return parsed;
	} catch {
		// Missing or corrupt cache — treat as absent.
	}
	return null;
}

function writeCache(file, payload) {
	try {
		mkdirSync(CACHE_DIR, { recursive: true });
		writeFileSync(file, JSON.stringify(payload));
	} catch {
		// A failed cache write just means we re-resolve next time.
	}
}

function maybeSpawnRefresh(cwd, cacheFile) {
	const lock = `${cacheFile}.lock`;
	try {
		if (Date.now() - statSync(lock).mtimeMs < REFRESH_LOCK_MS) return; // refresh already in flight
	} catch {
		// No lock yet.
	}
	try {
		mkdirSync(CACHE_DIR, { recursive: true });
		writeFileSync(lock, String(Date.now()));
	} catch {
		// If we can't take the lock, still attempt the refresh.
	}
	const child = spawn(process.execPath, [process.argv[1], "--refresh", cwd, cacheFile], {
		detached: true,
		stdio: "ignore",
	});
	child.unref();
}

// Build a web URL for the trail. Prefer whatever the CLI hands us; otherwise
// fall back to the canonical entire.io trail path used by the Pi extension.
function trailURL(trail, remote, branch) {
	const fromApi = trail.url || trail.html_url || trail.web_url;
	if (typeof fromApi === "string" && fromApi.startsWith("http")) return fromApi;
	if (!remote || !trail.number) return undefined;
	const slug = String(trail.title || branch || "")
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, 60);
	return `https://entire.io/gh/${remote.org}/${remote.repo}/trails/${trail.number}${slug ? `/${slug}` : ""}`;
}

// The CLI's JSON shape is defensive-mapped: field names have varied across
// versions, so accept the common aliases.
function normalizeTrail(raw) {
	if (!raw || typeof raw !== "object") return null;
	const number = raw.number ?? raw.trail_number ?? raw.id;
	const branch = raw.branch ?? raw.branch_name ?? raw.head_branch ?? raw.head;
	if (number == null || !branch) return null;
	return {
		number,
		branch: String(branch),
		title: raw.title ?? raw.name ?? null,
		status: raw.status ?? raw.state ?? null,
		url: raw.url ?? raw.html_url ?? raw.web_url ?? null,
	};
}

function parseTrails(stdout) {
	let json;
	try {
		json = JSON.parse(stdout);
	} catch {
		return [];
	}
	const list = Array.isArray(json) ? json : Array.isArray(json?.trails) ? json.trails : [];
	return list.map(normalizeTrail).filter(Boolean);
}

function render(result) {
	if (!result) return "";
	if (result.status === "found") {
		const label = `Trail #${result.number}${result.trailStatus ? ` ${result.trailStatus}` : ""}`;
		return color(CYAN, result.url ? hyperlink(result.url, label) : label);
	}
	if (result.status === "auth") return color(DIM, "Trail: run `entire login`");
	if (result.status === "error" && result.message) return color(DIM, `Trail: ${result.message}`);
	// "no-trail" and anything else render as empty (segment-only mode).
	return "";
}

// --- background refresh mode ---------------------------------------------

function runRefresh(cwd, cacheFile) {
	let result;
	try {
		const stdout = execFileSync(
			"entire",
			["trail", "list", "--json", "--status", "any", "-n", "100"],
			{ cwd, encoding: "utf8", timeout: REFRESH_TIMEOUT_MS, stdio: ["ignore", "pipe", "pipe"] },
		);
		const branch = getBranch(cwd);
		const remote = getRemote(cwd);
		const trail = parseTrails(stdout).find((t) => t.branch === branch);
		result = trail
			? {
					status: "found",
					number: trail.number,
					trailStatus: trail.status,
					url: trailURL(trail, remote, branch),
				}
			: { status: "no-trail" };
	} catch (err) {
		const stderr = (err?.stderr?.toString?.() || "").trim();
		const msg = (stderr || err?.message || "").toLowerCase();
		if (/not logged in|authentication required|unauthorized|run 'entire login'|please log in/.test(msg)) {
			result = { status: "auth" };
		} else if (/repository not found|not found|404|not enabled|no trail/.test(msg)) {
			// Repo isn't tracked by Entire (or has no trails) — render nothing.
			result = { status: "no-trail" };
		} else {
			// Keep it short; the statusline only has room for a hint.
			result = { status: "error", message: (stderr || "lookup failed").split("\n")[0].slice(0, 60) };
		}
	}
	writeCache(cacheFile, { ts: Date.now(), result });
}

// --- statusline (fast) mode ----------------------------------------------

function readStdinCwd() {
	try {
		const raw = readFileSync(0, "utf8");
		const input = raw ? JSON.parse(raw) : {};
		return input?.workspace?.current_dir || input?.cwd || process.cwd();
	} catch {
		return process.cwd();
	}
}

function runStatusline() {
	const cwd = readStdinCwd();
	const branch = getBranch(cwd);
	const remote = getRemote(cwd);
	// Not a git repo, detached HEAD, or no resolvable remote → nothing to show.
	if (!branch || !remote) return;

	const cacheFile = join(CACHE_DIR, `${cacheKey(remote, branch)}.json`);
	const cached = readCache(cacheFile);
	const age = cached ? Date.now() - cached.ts : Infinity;

	if (age > FRESH_MS) maybeSpawnRefresh(cwd, cacheFile);
	if (cached) {
		const out = render(cached.result);
		if (out) process.stdout.write(out);
	}
	// No cache yet → print nothing; the trail appears once the refresh lands.
}

// --- entry ----------------------------------------------------------------

if (process.argv[2] === "--refresh") {
	runRefresh(process.argv[3] || process.cwd(), process.argv[4]);
} else {
	runStatusline();
}

