1	/**
2	 * Entire Trails Extension
3	 *
4	 * Shows a clickable trail link in the Pi footer for the current git branch.
5	 * Resolves the trail through Entire's API, then watches the trail-scoped
6	 * agent-native review event SSE stream:
7	 *
8	 *   GET /api/v1/trails/:trail_id/reviews/events
9	 *   Accept: text/event-stream
10	 *
11	 * New live review comments are fetched and injected into the active Pi session
12	 * as user messages.
13	 */
14	
15	import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
16	import { execFileSync, execSync } from "node:child_process";
17	
18	interface TrailInfo {
19		id: string;
20		number: number;
21		title: string;
22		branch: string;
23		url: string;
24	}
25	
26	interface EntireAuth {
27		baseUrl: string;
28		token: string;
29	}
30	
31	interface CodeReviewEvent {
32		id?: string;
33		trail_id?: string;
34		review_id?: string | null;
35		// Backward-compatible with older event payloads.
36		review_session_id?: string | null;
37		actor_id?: string;
38		event_type?: string;
39		target_type?: string;
40		target_id?: string;
41		payload?: Record<string, unknown> | null;
42		created_at?: string;
43	}
44	
45	interface ReviewComment {
46		id: string;
47		actor_id?: string;
48		title?: string | null;
49		body?: string | null;
50		severity?: string | null;
51		review_id?: string | null;
52		// Backward-compatible with older comment payloads.
53		review_session_id?: string | null;
54		location?: {
55			file_path?: string | null;
56			start_line?: number | null;
57			end_line?: number | null;
58			selected_text?: string | null;
59		};
60	}
61	
62	interface SSEFrame {
63		event: string;
64		id?: string;
65		data?: unknown;
66	}
67	
68	type TrailLookup =
69		| { status: "none" }
70		| { status: "no-trail"; branch: string }
71		| { status: "error"; message: string }
72		| { status: "found"; trail: TrailInfo };
73	
74	type ExtensionCtx = {
75		cwd: string;
76		ui: {
77			notify: (message: string, level?: string) => void;
78			setStatus: (id: string, text: string | undefined) => void;
79			theme: { fg: (color: string, text: string) => string };
80		};
81	};
82	
83	function normalizeBaseUrl(raw: string | undefined): string {
84		return (raw?.trim() || "https://entire.io").replace(/\/+$/, "");
85	}
86	
87	function decodeStoredToken(raw: string): string {
88		const token = raw.trim();
89		const prefix = "go-keyring-base64:";
90		if (!token.startsWith(prefix)) return token;
91		try {
92			return Buffer.from(token.slice(prefix.length), "base64").toString("utf8").trim();
93		} catch {
94			return token;
95		}
96	}
97	
98	function getEntireAuth(): EntireAuth | null {
99		const baseUrl = normalizeBaseUrl(process.env.ENTIRE_API_BASE_URL);
100		const envToken = process.env.ENTIRE_API_TOKEN || process.env.ENTIRE_TOKEN;
101		if (envToken?.trim()) return { baseUrl, token: envToken.trim() };
102	
103		try {
104			const stored = execFileSync(
105				"security",
106				["find-generic-password", "-s", "entire-cli", "-a", baseUrl, "-w"],
107				{ encoding: "utf8", timeout: 5000 },
108			);
109			const token = decodeStoredToken(stored);
110			return token ? { baseUrl, token } : null;
111		} catch {
112			return null;
113		}
114	}
115	
116	function apiURL(auth: EntireAuth, path: string): string {
117		return `${auth.baseUrl}${path.startsWith("/") ? path : `/${path}`}`;
118	}
119	
120	async function responseError(response: Response): Promise<string> {
121		let text = "";
122		try {
123			text = await response.text();
124		} catch {
125			// Ignore; fall through to status text.
126		}
127		try {
128			const parsed = JSON.parse(text) as { error?: unknown };
129			if (typeof parsed.error === "string" && parsed.error.trim()) return parsed.error.trim();
130			if (parsed.error && typeof parsed.error === "object") {
131				const message = (parsed.error as { message?: unknown }).message;
132				if (typeof message === "string" && message.trim()) return message.trim();
133			}
134		} catch {
135			// Not JSON.
136		}
137		return text.trim() || response.statusText || `HTTP ${response.status}`;
138	}
139	
140	async function fetchJSON<T>(auth: EntireAuth, path: string, signal?: AbortSignal): Promise<T> {
141		const response = await fetch(apiURL(auth, path), {
142			headers: {
143				Accept: "application/json",
144				Authorization: `Bearer ${auth.token}`,
145			},
146			signal,
147		});
148		if (!response.ok) throw new Error(await responseError(response));
149		return (await response.json()) as T;
150	}
151	
152	function getGitRemote(cwd: string): { org: string; repo: string } | null {
153		try {
154			const remote = execSync("git remote get-url origin", { cwd, encoding: "utf-8" }).trim();
155	
156			const entireMatch = remote.match(/^entire:\/\/[^/]+\/gh\/([^/]+)\/([^/?#]+?)(?:\.git)?(?:[?#].*)?$/);
157			if (entireMatch) return { org: decodeURIComponent(entireMatch[1]!), repo: decodeURIComponent(entireMatch[2]!) };
158	
159			const githubMatch = remote.match(/github\.com[/:]([^/]+)\/(.+?)(?:\.git)?$/);
160			return githubMatch ? { org: githubMatch[1]!, repo: githubMatch[2]! } : null;
161		} catch {
162			return null;
163		}
164	}
165	
166	function getGitBranch(cwd: string): string | null {
167		try {
168			return execSync("git branch --show-current", { cwd, encoding: "utf-8" }).trim() || null;
169		} catch {
170			return null;
171		}
172	}
173	
174	function trailURL(remote: { org: string; repo: string }, trail: { number: number; title?: string }, branch: string): string {
175		const slug = (trail.title || branch)
176			.toLowerCase()
177			.replace(/[^a-z0-9]+/g, "-")
178			.replace(/^-+|-+$/g, "")
179			.slice(0, 60);
180		return `https://entire.io/gh/${remote.org}/${remote.repo}/trails/${trail.number}${slug ? `/${slug}` : ""}`;
181	}
182	
183	async function getTrailForBranch(cwd: string): Promise<TrailLookup> {
184		const branch = getGitBranch(cwd);
185		const remote = getGitRemote(cwd);
186		if (!branch || !remote) return { status: "none" };
187	
188		const auth = getEntireAuth();
189		if (!auth) return { status: "error", message: 'Authentication via "entire auth login" required' };
190	
191		try {
192			const path = `/api/v1/trails/gh/${encodeURIComponent(remote.org)}/${encodeURIComponent(remote.repo)}`;
193			const json = await fetchJSON<{
194				trails?: Array<{ id?: string; trail_id?: string; number?: number; branch?: string; title?: string }>;
195			}>(auth, path);
196	
197			const trail = (json.trails ?? []).find((t) => t.branch === branch);
198			if (!trail?.number) return { status: "no-trail", branch };
199	
200			const id = trail.id || trail.trail_id;
201			if (!id) return { status: "error", message: `Trail #${trail.number} is missing id` };
202	
203			return {
204				status: "found",
205				trail: {
206					id,
207					number: trail.number,
208					title: trail.title ?? branch,
209					branch,
210					url: trailURL(remote, { number: trail.number, title: trail.title }, branch),
211				},
212			};
213		} catch (err) {
214			const message = ((err as Error).message || "error").trim().split("\n")[0] ?? "error";
215			return { status: "error", message };
216		}
217	}
218	
219	function payloadString(payload: Record<string, unknown> | null | undefined, key: string): string {
220		const value = payload?.[key];
221		return typeof value === "string" ? value : "";
222	}
223	
224	function payloadNumber(payload: Record<string, unknown> | null | undefined, key: string): number | null {
225		const value = payload?.[key];
226		return typeof value === "number" && Number.isFinite(value) ? value : null;
227	}
228	
229	function fencedText(label: string, text: string): string[] {
230		return text.trim() ? [label, "```", text.trim(), "```"] : [];
231	}
232	
233	function formatReviewComment(trail: TrailInfo, event: CodeReviewEvent, comment?: ReviewComment): string {
234		const payload = event.payload ?? null;
235		const commentId = comment?.id || event.target_id || "unknown";
236		const body = (comment?.body || payloadString(payload, "body")).trim();
237		const file = comment?.location?.file_path || payloadString(payload, "file_path");
238		const severity = comment?.severity || payloadString(payload, "severity");
239		const startLine = comment?.location?.start_line ?? payloadNumber(payload, "start_line");
240		const endLine = comment?.location?.end_line ?? payloadNumber(payload, "end_line");
241		const selectedText = (comment?.location?.selected_text || payloadString(payload, "selected_text")).trim();
242		const location = file
243			? `${file}${startLine ? `:${startLine}${endLine && endLine !== startLine ? `-${endLine}` : ""}` : ""}`
244			: "";
245	
246		return [
247			"Entire Trail review comment",
248			`ID: ${commentId}`,
249			`URL: ${trail.url}`,
250			severity ? `Severity: ${severity}` : "",
251			location ? `Context: ${location}` : "",
252			...fencedText("Selected context:", selectedText),
253			body,
254		]
255			.filter(Boolean)
256			.join("\n");
257	}
258	
259	function formatTrailLookupError(message: string): string {
260		return /auth|login|unauthorized|forbidden|not authenticated/i.test(message)
261			? 'Authentication via "entire auth login" required'
262			: message;
263	}
264	
265	function trailLookupMessage(result: Exclude<TrailLookup, { status: "found" }>): string {
266		if (result.status === "no-trail") return `No trail found for branch ${result.branch}.`;
267		if (result.status === "error") return formatTrailLookupError(result.message);
268		return "Cannot resolve current branch/repo trail.";
269	}
270	
271	function reviewEventsPath(trailId: string): string {
272		return `/api/v1/trails/${encodeURIComponent(trailId)}/reviews/events`;
273	}
274	
275	async function latestEventCursor(auth: EntireAuth, trailId: string, signal: AbortSignal): Promise<string> {
276		let after = "0";
277		for (let i = 0; i < 100; i++) {
278			const page = await fetchJSON<{ events?: CodeReviewEvent[] }>(
279				auth,
280				`${reviewEventsPath(trailId)}?after=${encodeURIComponent(after)}&limit=1000`,
281				signal,
282			);
283			const events = page.events ?? [];
284			if (events.length === 0) return after === "0" ? "" : after;
285			const last = events[events.length - 1];
286			if (!last?.id) return after === "0" ? "" : after;
287			after = last.id;
288			if (events.length < 1000) return after;
289		}
290		return after === "0" ? "" : after;
291	}
292	
293	async function fetchReviewComment(
294		auth: EntireAuth,
295		trailId: string,
296		reviewId: string,
297		commentId: string,
298		signal: AbortSignal,
299	): Promise<ReviewComment | undefined> {
300		try {
301			return await fetchJSON<ReviewComment>(
302				auth,
303				`/api/v1/trails/${encodeURIComponent(trailId)}/reviews/${encodeURIComponent(reviewId)}/comments/${encodeURIComponent(commentId)}`,
304				signal,
305			);
306		} catch {
307			return undefined;
308		}
309	}
310	
311	function isObject(value: unknown): value is Record<string, unknown> {
312		return !!value && typeof value === "object" && !Array.isArray(value);
313	}
314	
315	async function readSSE(
316		response: Response,
317		signal: AbortSignal,
318		onFrame: (frame: SSEFrame) => Promise<void>,
319	): Promise<"reconnect" | "forbidden" | "error" | "eof" | "done"> {
320		const reader = response.body?.getReader();
321		if (!reader) return "eof";
322	
323		const decoder = new TextDecoder();
324		let pending = "";
325		let eventName = "";
326		let eventId = "";
327		let dataLines: string[] = [];
328	
329		const dispatch = async (): Promise<"continue" | "reconnect" | "forbidden" | "error"> => {
330			if (!eventName && !eventId && dataLines.length === 0) return "continue";
331			const name = eventName || "message";
332			const id = eventId || undefined;
333			const rawData = dataLines.join("\n");
334			eventName = "";
335			eventId = "";
336			dataLines = [];
337	
338			let data: unknown = rawData;
339			if (rawData) {
340				try {
341					data = JSON.parse(rawData);
342				} catch {
343					// Keep raw string.
344				}
345			}
346	
347			await onFrame({ event: name, id, data });
348			if (name === "reconnect") return "reconnect";
349			if (name === "forbidden") return "forbidden";
350			if (name === "error") return "error";
351			return "continue";
352		};
353	
354		while (!signal.aborted) {
355			const { done, value } = await reader.read();
356			if (done) break;
357			pending += decoder.decode(value, { stream: true });
358	
359			for (;;) {
360				const nl = pending.search(/\r?\n/);
361				if (nl < 0) break;
362				const line = pending.slice(0, nl).replace(/\r$/, "");
363				pending = pending.slice(line.length + (pending[line.length] === "\r" ? 2 : 1));
364	
365				if (line === "") {
366					const reason = await dispatch();
367					if (reason !== "continue") return reason;
368					continue;
369				}
370				if (line.startsWith(":")) continue;
371	
372				const colon = line.indexOf(":");
373				const field = colon >= 0 ? line.slice(0, colon) : line;
374				const value = colon >= 0 ? line.slice(colon + 1).replace(/^ /, "") : "";
375				if (field === "event") eventName = value;
376				else if (field === "id") eventId = value;
377				else if (field === "data") dataLines.push(value);
378			}
379		}
380	
381		if (signal.aborted) return "done";
382		const reason = await dispatch();
383		return reason === "continue" ? "eof" : reason;
384	}
385	
386	function sleep(ms: number, signal: AbortSignal): Promise<void> {
387		return new Promise((resolve) => {
388			const timer = setTimeout(resolve, ms);
389			if (signal.aborted) {
390				clearTimeout(timer);
391				resolve();
392				return;
393			}
394			signal.addEventListener(
395				"abort",
396				() => {
397					clearTimeout(timer);
398					resolve();
399				},
400				{ once: true },
401			);
402		});
403	}
404	
405	export default function (pi: ExtensionAPI) {
406		let watcher: AbortController | undefined;
407		let watchedTrail: TrailInfo | undefined;
408		let paused = false;
409		const seenCommentIds = new Set<string>();
410		let currentTrailLookup: TrailLookup = { status: "none" };
411		let watchStatus: "idle" | "watching" | "paused" | "error" = "idle";
412		let watchStatusMessage = "";
413	
414		function renderEntireTrailsStatus(ui: ExtensionCtx["ui"]) {
415			// Clear legacy split footer slots if this file was hot-reloaded from an older version.
416			ui.setStatus("trail-link", undefined);
417			ui.setStatus("trail-watch", undefined);
418	
419			const result = currentTrailLookup;
420			if (result.status === "none") {
421				ui.setStatus("entire-trails", undefined);
422				return;
423			}
424	
425			if (result.status === "no-trail") {
426				ui.setStatus("entire-trails", ui.theme.fg("dim", `No trail for ${result.branch}`));
427				return;
428			}
429	
430			if (result.status === "error") {
431				ui.setStatus("entire-trails", ui.theme.fg("dim", formatTrailLookupError(result.message)));
432				return;
433			}
434	
435			const trail = result.trail;
436			const label = `Trail #${trail.number}`;
437			const hyperlink = `\x1b]8;;${trail.url}\x07${label}\x1b]8;;\x07`;
438			let text = ui.theme.fg("accent", hyperlink);
439			if (watchStatus === "watching") text += ui.theme.fg("dim", " watching");
440			if (watchStatus === "paused") text += ui.theme.fg("dim", " paused");
441			if (watchStatus === "error") text += ui.theme.fg("dim", ` error: ${watchStatusMessage}`);
442			ui.setStatus("entire-trails", text);
443		}
444	
445		async function updateEntireTrailsStatus(cwd: string, ui: ExtensionCtx["ui"]) {
446			currentTrailLookup = await getTrailForBranch(cwd);
447			renderEntireTrailsStatus(ui);
448		}
449	
450		function stopWatcher() {
451			const controller = watcher;
452			watcher = undefined;
453			watchedTrail = undefined;
454			seenCommentIds.clear();
455			controller?.abort();
456		}
457	
458		async function handleReviewFrame(ctx: ExtensionCtx, auth: EntireAuth, trail: TrailInfo, signal: AbortSignal, frame: SSEFrame) {
459			if (frame.event !== "comment.created" || !isObject(frame.data)) return;
460			const event = frame.data as CodeReviewEvent;
461			const commentId = event.target_id;
462			if (!commentId || seenCommentIds.has(commentId)) return;
463			seenCommentIds.add(commentId);
464	
465			const reviewId =
466				event.review_id ||
467				payloadString(event.payload, "review_id") ||
468				event.review_session_id ||
469				payloadString(event.payload, "review_session_id");
470			const comment = reviewId ? await fetchReviewComment(auth, trail.id, reviewId, commentId, signal) : undefined;
471			const message = formatReviewComment(trail, event, comment);
472			try {
473				pi.sendUserMessage(message, { deliverAs: "steer" });
474			} catch {
475				try {
476					pi.sendUserMessage(message);
477				} catch {
478					// Never crash Pi because the watcher failed to inject.
479				}
480			}
481		}
482	
483		async function runReviewEventWatcher(ctx: ExtensionCtx, auth: EntireAuth, trail: TrailInfo, controller: AbortController) {
484			let lastEventId = "";
485			let backoff = 500;
486			try {
487				// Start after the current event log so historical comments are not injected on startup.
488				lastEventId = await latestEventCursor(auth, trail.id, controller.signal);
489	
490				while (!controller.signal.aborted) {
491					const headers: Record<string, string> = {
492						Accept: "text/event-stream",
493						Authorization: `Bearer ${auth.token}`,
494					};
495					if (lastEventId) headers["Last-Event-ID"] = lastEventId;
496	
497					try {
498						const response = await fetch(apiURL(auth, reviewEventsPath(trail.id)), {
499							headers,
500							signal: controller.signal,
501						});
502						if (!response.ok) throw new Error(await responseError(response));
503	
504						const reason = await readSSE(response, controller.signal, async (frame) => {
505							if (frame.id) lastEventId = frame.id;
506							await handleReviewFrame(ctx, auth, trail, controller.signal, frame);
507						});
508	
509						if (controller.signal.aborted || reason === "done") break;
510						if (reason === "forbidden") throw new Error("access revoked");
511						if (reason === "error") throw new Error("server error");
512						if (reason === "reconnect") {
513							backoff = 500;
514							continue;
515						}
516					} catch (err) {
517						if (controller.signal.aborted) break;
518						watchStatus = "error";
519						watchStatusMessage = formatTrailLookupError(((err as Error).message || "connection error").split("\n")[0] ?? "connection error");
520						renderEntireTrailsStatus(ctx.ui);
521						await sleep(backoff, controller.signal);
522						backoff = Math.min(backoff * 2, 30000);
523					}
524				}
525			} finally {
526				if (watcher === controller) {
527					watcher = undefined;
528					watchedTrail = undefined;
529					seenCommentIds.clear();
530					watchStatus = paused ? "paused" : "idle";
531					renderEntireTrailsStatus(ctx.ui);
532				}
533			}
534		}
535	
536		async function ensureWatcher(
537			ctx: ExtensionCtx,
538			opts: { notify?: boolean; silentMissing?: boolean; forceRestart?: boolean } = {},
539		) {
540			if (paused) {
541				watchStatus = "paused";
542				renderEntireTrailsStatus(ctx.ui);
543				return false;
544			}
545	
546			const result = await getTrailForBranch(ctx.cwd);
547			currentTrailLookup = result;
548			if (result.status !== "found") {
549				stopWatcher();
550				watchStatus = "idle";
551				renderEntireTrailsStatus(ctx.ui);
552				if (!opts.silentMissing) ctx.ui.notify(trailLookupMessage(result), "error");
553				return false;
554			}
555	
556			const auth = getEntireAuth();
557			if (!auth) {
558				stopWatcher();
559				watchStatus = "error";
560				watchStatusMessage = 'Authentication via "entire auth login" required';
561				renderEntireTrailsStatus(ctx.ui);
562				return false;
563			}
564	
565			if (!opts.forceRestart && watcher && watchedTrail?.id === result.trail.id) {
566				watchStatus = "watching";
567				renderEntireTrailsStatus(ctx.ui);
568				if (opts.notify) ctx.ui.notify(`Already watching trail #${result.trail.number}.`, "info");
569				return true;
570			}
571	
572			stopWatcher();
573			seenCommentIds.clear();
574	
575			const controller = new AbortController();
576			watcher = controller;
577			watchedTrail = result.trail;
578			watchStatus = "watching";
579			watchStatusMessage = "";
580			renderEntireTrailsStatus(ctx.ui);
581			if (opts.notify) ctx.ui.notify(`Watching trail #${result.trail.number} review comments.`, "info");
582			void runReviewEventWatcher(ctx, auth, result.trail, controller);
583			return true;
584		}
585	
586		pi.registerCommand("trail-watch", {
587			description: "Show/control automatic Entire trails review comment watching (pause, resume)",
588			handler: async (args: string, ctx: ExtensionCtx) => {
589				const action = args.trim().toLowerCase();
590	
591				if (action === "pause") {
592					paused = true;
593					stopWatcher();
594					watchStatus = "paused";
595					renderEntireTrailsStatus(ctx.ui);
596					ctx.ui.notify("Paused trail review watcher. Use /trail-watch resume to turn it back on.", "info");
597					return;
598				}
599	
600				if (action === "resume") {
601					paused = false;
602					await ensureWatcher(ctx, { notify: true, forceRestart: true });
603					return;
604				}
605	
606				if (action === "") {
607					if (paused) {
608						ctx.ui.notify("Trail watcher is paused. Use /trail-watch resume to turn it back on.", "info");
609						return;
610					}
611					if (watcher && watchedTrail) {
612						ctx.ui.notify(`Watching trail #${watchedTrail.number} review comments. Use /trail-watch pause to pause.`, "info");
613						return;
614					}
615					const result = await getTrailForBranch(ctx.cwd);
616					if (result.status === "found") {
617						ctx.ui.notify(`Trail watcher is not running for #${result.trail.number}; reload Pi or use /trail-watch resume.`, "info");
618						return;
619					}
620					ctx.ui.notify(trailLookupMessage(result), "info");
621					return;
622				}
623	
624				ctx.ui.notify("Usage: /trail-watch [pause|resume]", "error");
625			},
626		});
627	
628		pi.on("session_start", async (_event, ctx: ExtensionCtx) => {
629			await updateEntireTrailsStatus(ctx.cwd, ctx.ui);
630			void ensureWatcher(ctx, { silentMissing: true });
631		});
632	
633		pi.on("agent_end", async (_event, ctx: ExtensionCtx) => {
634			await updateEntireTrailsStatus(ctx.cwd, ctx.ui);
635			void ensureWatcher(ctx, { silentMissing: true });
636		});
637	
638		pi.on("session_shutdown", () => {
639			stopWatcher();
640		});
641	}
642

