53	// localDevHookCommand builds a local-dev hook command for the given hook name,
54	// delegating to scripts/entire-dev for the build-probe-and-fallback logic.
55	func localDevHookCommand(hookName string) string {
56		return fmt.Sprintf("%shooks claude-code %s", localDevHookCmdPrefix, hookName)
57	}
58	
59	// InstallHooks installs Claude Code hooks in .claude/settings.json.
60	// If force is true, removes existing Entire hooks before installing.
61	// Returns the number of hooks installed.
62	func (c *ClaudeCodeAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
63		// Use repo root instead of CWD to find .claude directory
64		// This ensures hooks are installed correctly when run from a subdirectory
65		repoRoot, err := paths.WorktreeRoot(ctx)
66		if err != nil {
67			// Fallback to CWD if not in a git repo (e.g., during tests)
68			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
69			if err != nil {
70				return 0, fmt.Errorf("failed to get current directory: %w", err)
71			}
72		}
73	
74		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
75	
76		// Read existing settings if they exist
77		var rawSettings map[string]json.RawMessage
78	
79		// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
80		var rawHooks map[string]json.RawMessage
81	
82		// rawPermissions preserves unknown permission fields (e.g., "ask")
83		var rawPermissions map[string]json.RawMessage
84	
85		existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + settings file name
86		if readErr == nil {
87			if err := json.Unmarshal(existingData, &rawSettings); err != nil {
88				return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
89			}
90			if hooksRaw, ok := rawSettings["hooks"]; ok {
91				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
92					return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
93				}
94			}
95			if permRaw, ok := rawSettings["permissions"]; ok {
96				if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
97					return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
98				}
99			}
100		} else {
101			rawSettings = make(map[string]json.RawMessage)
102		}
103	
104		if rawHooks == nil {
105			rawHooks = make(map[string]json.RawMessage)
106		}
107		if rawPermissions == nil {
108			rawPermissions = make(map[string]json.RawMessage)
109		}
110	
111		// Parse only the hook types we need to modify
112		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
113		parseHookType(rawHooks, "SessionStart", &sessionStart)
114		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
115		parseHookType(rawHooks, "Stop", &stop)
116		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
117		parseHookType(rawHooks, "PreToolUse", &preToolUse)
118		parseHookType(rawHooks, "PostToolUse", &postToolUse)
119	
120		// If force is true, remove all existing Entire hooks first
121		if force {
122			sessionStart = removeEntireHooks(sessionStart)
123			sessionEnd = removeEntireHooks(sessionEnd)
124			stop = removeEntireHooks(stop)
125			userPromptSubmit = removeEntireHooks(userPromptSubmit)
126			preToolUse = removeEntireHooksFromMatchers(preToolUse)
127			postToolUse = removeEntireHooksFromMatchers(postToolUse)
128		}
129	
130		// Define hook commands
131		var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, postTodoCmd string
132		if localDev {
133			sessionStartCmd = localDevHookCommand(HookNameSessionStart)
134			sessionEndCmd = localDevHookCommand(HookNameSessionEnd)
135			stopCmd = localDevHookCommand(HookNameStop)
136			userPromptSubmitCmd = localDevHookCommand(HookNameUserPromptSubmit)
137			preTaskCmd = localDevHookCommand(HookNamePreTask)
138			postTaskCmd = localDevHookCommand(HookNamePostTask)
139			postTodoCmd = localDevHookCommand(HookNamePostTodo)
140		} else {
141			sessionStartCmd = agent.WrapProductionJSONWarningHookCommand("entire hooks claude-code session-start", agent.WarningFormatMultiLine)
142			sessionEndCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code session-end")
143			stopCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code stop")
144			userPromptSubmitCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code user-prompt-submit")
145			preTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code pre-task")
146			postTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code post-task")
147			postTodoCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code post-todo")
148		}
149	
150		count := 0
151	
152		// Add hooks if they don't exist
153		if !hookCommandExists(sessionStart, sessionStartCmd) {
154			sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
155			count++
156		}
157		if !hookCommandExists(sessionEnd, sessionEndCmd) {
158			sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
159			count++
160		}
161		if !hookCommandExists(stop, stopCmd) {
162			stop = addHookToMatcher(stop, "", stopCmd)
163			count++
164		}
165		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
166			userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
167			count++
168		}
169		if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
170			preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
171			count++
172		}
173		if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
174			postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
175			count++
176		}
177		if !hookCommandExistsWithMatcher(postToolUse, "TodoWrite", postTodoCmd) {
178			postToolUse = addHookToMatcher(postToolUse, "TodoWrite", postTodoCmd)
179			count++
180		}
181	
182		// Add permissions.deny rule if not present
183		permissionsChanged := false
184		var denyRules []string
185		if denyRaw, ok := rawPermissions["deny"]; ok {
186			if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
187				return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
188			}
189		}
190		if !slices.Contains(denyRules, metadataDenyRule) {
191			denyRules = append(denyRules, metadataDenyRule)
192			denyJSON, err := json.Marshal(denyRules)
193			if err != nil {
194				return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
195			}
196			rawPermissions["deny"] = denyJSON
197			permissionsChanged = true
198		}
199	
200		if count == 0 && !permissionsChanged {
201			return 0, nil // All hooks and permissions already installed
202		}
203	
204		// Marshal modified hook types back to rawHooks
205		marshalHookType(rawHooks, "SessionStart", sessionStart)
206		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
207		marshalHookType(rawHooks, "Stop", stop)
208		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
209		marshalHookType(rawHooks, "PreToolUse", preToolUse)
210		marshalHookType(rawHooks, "PostToolUse", postToolUse)
211	
212		// Marshal hooks and update raw settings
213		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
214		if err != nil {
215			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
216		}
217		rawSettings["hooks"] = hooksJSON
218	
219		// Marshal permissions and update raw settings
220		permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
221		if err != nil {
222			return 0, fmt.Errorf("failed to marshal permissions: %w", err)
223		}
224		rawSettings["permissions"] = permJSON
225	
226		// Write back to file
227		if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
228			return 0, fmt.Errorf("failed to create .claude directory: %w", err)
229		}
230	
231		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
232		if err != nil {
233			return 0, fmt.Errorf("failed to marshal settings: %w", err)
234		}
235	
236		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
237			return 0, fmt.Errorf("failed to write settings.json: %w", err)
238		}
239	
240		return count, nil
241	}
242	
243	// parseHookType parses a specific hook type from rawHooks into the target slice.
244	// Silently ignores parse errors (leaves target unchanged).
245	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]ClaudeHookMatcher) {
246		if data, ok := rawHooks[hookType]; ok {
247			//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
248			json.Unmarshal(data, target)
249		}
250	}
251	
252	// marshalHookType marshals a hook type back to rawHooks.
253	// If the slice is empty, removes the key from rawHooks.
254	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []ClaudeHookMatcher) {
255		if len(matchers) == 0 {
256			delete(rawHooks, hookType)
257			return
258		}
259		data, err := jsonutil.MarshalWithNoHTMLEscape(matchers)
260		if err != nil {
261			return // Silently ignore marshal errors (shouldn't happen)
262		}
263		rawHooks[hookType] = data
264	}
265	
266	// UninstallHooks removes Entire hooks from Claude Code settings.
267	func (c *ClaudeCodeAgent) UninstallHooks(ctx context.Context) error {
268		// Use repo root to find .claude directory when run from a subdirectory
269		repoRoot, err := paths.WorktreeRoot(ctx)
270		if err != nil {
271			repoRoot = "." // Fallback to CWD if not in a git repo
272		}
273		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
274		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
275		if err != nil {
276			return nil //nolint:nilerr // No settings file means nothing to uninstall
277		}
278	
279		var rawSettings map[string]json.RawMessage
280		if err := json.Unmarshal(data, &rawSettings); err != nil {
281			return fmt.Errorf("failed to parse settings.json: %w", err)
282		}
283	
284		// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
285		var rawHooks map[string]json.RawMessage
286		if hooksRaw, ok := rawSettings["hooks"]; ok {
287			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
288				return fmt.Errorf("failed to parse hooks: %w", err)
289			}
290		}
291		if rawHooks == nil {
292			rawHooks = make(map[string]json.RawMessage)
293		}
294	
295		// Parse only the hook types we need to modify
296		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
297		parseHookType(rawHooks, "SessionStart", &sessionStart)
298		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
299		parseHookType(rawHooks, "Stop", &stop)
300		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
301		parseHookType(rawHooks, "PreToolUse", &preToolUse)
302		parseHookType(rawHooks, "PostToolUse", &postToolUse)
303	
304		// Remove Entire hooks from all hook types
305		sessionStart = removeEntireHooks(sessionStart)
306		sessionEnd = removeEntireHooks(sessionEnd)
307		stop = removeEntireHooks(stop)
308		userPromptSubmit = removeEntireHooks(userPromptSubmit)
309		preToolUse = removeEntireHooksFromMatchers(preToolUse)
310		postToolUse = removeEntireHooksFromMatchers(postToolUse)
311	
312		// Marshal modified hook types back to rawHooks
313		marshalHookType(rawHooks, "SessionStart", sessionStart)
314		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
315		marshalHookType(rawHooks, "Stop", stop)
316		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
317		marshalHookType(rawHooks, "PreToolUse", preToolUse)
318		marshalHookType(rawHooks, "PostToolUse", postToolUse)
319	
320		// Also remove the metadata deny rule from permissions
321		var rawPermissions map[string]json.RawMessage
322		if permRaw, ok := rawSettings["permissions"]; ok {
323			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
324				// If parsing fails, just skip permissions cleanup
325				rawPermissions = nil
326			}
327		}
328	
329		if rawPermissions != nil {
330			if denyRaw, ok := rawPermissions["deny"]; ok {
331				var denyRules []string
332				if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
333					// Filter out the metadata deny rule
334					filteredRules := make([]string, 0, len(denyRules))
335					for _, rule := range denyRules {
336						if rule != metadataDenyRule {
337							filteredRules = append(filteredRules, rule)
338						}
339					}
340					if len(filteredRules) > 0 {
341						denyJSON, err := json.Marshal(filteredRules)
342						if err == nil {
343							rawPermissions["deny"] = denyJSON
344						}
345					} else {
346						// Remove empty deny array
347						delete(rawPermissions, "deny")
348					}
349				}
350			}
351	
352			// If permissions is empty, remove it entirely
353			if len(rawPermissions) > 0 {
354				permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
355				if err == nil {
356					rawSettings["permissions"] = permJSON
357				}
358			} else {
359				delete(rawSettings, "permissions")
360			}
361		}
362	
363		// Marshal hooks back (preserving unknown hook types)
364		if len(rawHooks) > 0 {
365			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
366			if err != nil {
367				return fmt.Errorf("failed to marshal hooks: %w", err)
368			}
369			rawSettings["hooks"] = hooksJSON
370		} else {
371			delete(rawSettings, "hooks")
372		}
373	
374		// Write back
375		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
376		if err != nil {
377			return fmt.Errorf("failed to marshal settings: %w", err)
378		}
379		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
380			return fmt.Errorf("failed to write settings.json: %w", err)
381		}
382		return nil
383	}
384	
385	// AreHooksInstalled checks if Entire hooks are installed.
386	func (c *ClaudeCodeAgent) AreHooksInstalled(ctx context.Context) bool {
387		// Use repo root to find .claude directory when run from a subdirectory
388		repoRoot, err := paths.WorktreeRoot(ctx)
389		if err != nil {
390			repoRoot = "." // Fallback to CWD if not in a git repo
391		}
392		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
393		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
394		if err != nil {
395			return false
396		}
397	
398		var settings ClaudeSettings
399		if err := json.Unmarshal(data, &settings); err != nil {
400			return false
401		}
402	
403		// Check for at least one of our hooks (new, wrapped, or legacy format)
404		return hasEntireHook(settings.Hooks.Stop)
405	}
406	
407	// Helper functions for hook management
408	
409	func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
410		for _, matcher := range matchers {
411			for _, hook := range matcher.Hooks {
412				if hook.Command == command {
413					return true
414				}
415			}
416		}
417		return false
418	}
419	
420	func hasEntireHook(matchers []ClaudeHookMatcher) bool {
421		for _, matcher := range matchers {
422			for _, hook := range matcher.Hooks {
423				if isEntireHook(hook.Command) {
424					return true
425				}
426			}
427		}
428		return false
429	}
430	
431	func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
432		for _, matcher := range matchers {
433			if matcher.Matcher == matcherName {
434				for _, hook := range matcher.Hooks {
435					if hook.Command == command {
436						return true
437					}
438				}
439			}
440		}
441		return false
442	}
443	
444	func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
445		entry := ClaudeHookEntry{
446			Type:    "command",
447			Command: command,
448		}
449	
450		// If no matcher name, add to a matcher with empty string
451		if matcherName == "" {
452			for i, matcher := range matchers {
453				if matcher.Matcher == "" {
454					matchers[i].Hooks = append(matchers[i].Hooks, entry)
455					return matchers
456				}
457			}
458			return append(matchers, ClaudeHookMatcher{
459				Matcher: "",
460				Hooks:   []ClaudeHookEntry{entry},
461			})
462		}
463	
464		// Find or create matcher with the given name
465		for i, matcher := range matchers {
466			if matcher.Matcher == matcherName {
467				matchers[i].Hooks = append(matchers[i].Hooks, entry)
468				return matchers
469			}
470		}
471	
472		return append(matchers, ClaudeHookMatcher{
473			Matcher: matcherName,
474			Hooks:   []ClaudeHookEntry{entry},
475		})
476	}
477	
478	// isEntireHook checks if a command is an Entire hook (old or new format)
479	func isEntireHook(command string) bool {
480		return agent.IsManagedHookCommand(command, entireHookPrefixes)
481	}
482	
483	// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
484	func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
485		result := make([]ClaudeHookMatcher, 0, len(matchers))
486		for _, matcher := range matchers {
487			filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
488			for _, hook := range matcher.Hooks {
489				if !isEntireHook(hook.Command) {
490					filteredHooks = append(filteredHooks, hook)
491				}
492			}
493			// Only keep the matcher if it has hooks remaining
494			if len(filteredHooks) > 0 {
495				matcher.Hooks = filteredHooks
496				result = append(result, matcher)
497			}
498		}
499		return result
500	}
501	
502	// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
503	// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
504	func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
505		// Same logic as removeEntireHooks - both work on the same structure
506		return removeEntireHooks(matchers)
507	}
