193	// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
194	const stopHookSentinel = "hooks claude-code stop"
195	
196	// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
197	// Falls back silently after a timeout.
198	func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
199		const (
200			maxWait      = 3 * time.Second
201			pollInterval = 50 * time.Millisecond
202			tailBytes    = 4096
203			maxSkew      = 2 * time.Second
204		)
205	
206		logCtx := logging.WithComponent(ctx, "agent.claudecode")
207	
208		// Fast path: skip the poll loop when the sentinel can't possibly appear.
209		// - File doesn't exist: nothing to poll.
210		// - File is stale (unmodified for 2+ min): agent isn't running anymore.
211		//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
212		//   without firing stop hook).
213		const staleThreshold = 2 * time.Minute
214		info, err := os.Stat(transcriptPath)
215		if err != nil {
216			// Most likely the file doesn't exist; other errors (permission, etc.)
217			// would also prevent polling, so skip the wait either way.
218			return
219		}
220		fileAge := time.Since(info.ModTime())
221		if fileAge > staleThreshold {
222			logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
223				slog.Duration("file_age", fileAge),
224			)
225			return
226		}
227	
228		deadline := time.Now().Add(maxWait)
229		for time.Now().Before(deadline) {
230			if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
231				logging.Debug(logCtx, "transcript flush sentinel found",
232					slog.Duration("wait", time.Since(hookStartTime)),
233				)
234				return
235			}
236			time.Sleep(pollInterval)
237		}
238		logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
239			slog.Duration("timeout", maxWait),
240		)
241	}
242	
243	// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
244	func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
245		f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
246		if err != nil {
247			return false
248		}
249		defer f.Close()
250	
251		info, err := f.Stat()
252		if err != nil {
253			return false
254		}
255		offset := info.Size() - tailBytes
256		if offset < 0 {
257			offset = 0
258		}
259		buf := make([]byte, info.Size()-offset)
260		if _, err := f.ReadAt(buf, offset); err != nil {
261			return false
262		}
263	
264		lines := strings.Split(string(buf), "\n")
265		for _, line := range lines {
266			line = strings.TrimSpace(line)
267			if line == "" || !strings.Contains(line, stopHookSentinel) {
268				continue
269			}
270	
271			var entry struct {
272				Timestamp string `json:"timestamp"`
273			}
274			if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
275				continue
276			}
277			ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
278			if err != nil {
279				ts, err = time.Parse(time.RFC3339, entry.Timestamp)
280				if err != nil {
281					continue
282				}
283			}
284			// Validate timestamp is within acceptable range:
285			// - Not too far in the past (before hook started minus skew)
286			// - Not too far in the future (after hook started plus skew)
287			lowerBound := hookStartTime.Add(-maxSkew)
288			upperBound := hookStartTime.Add(maxSkew)
289			if ts.After(lowerBound) && ts.Before(upperBound) {
290				return true
291			}
292		}
293		return false
294	}
