	scaffoldResult, err := scaffoldSearchSubagent(ctx, ag)
	if err != nil {
		return 0, fmt.Errorf("failed to scaffold %s search subagent: %w", ag.Name(), err)
	}
	reportSearchSubagentScaffold(w, ag, scaffoldResult)

